# hypothesis: A callback Protocol with a positional-only parameter and a defaulted keyword parameter accepts functions with different parameter names, but rejects one with a required keyword-only parameter.
from typing import Callable, Protocol, assert_type


class Handler(Protocol):
    def __call__(self, value: int, /, scale: int = 1) -> int: ...


def double(x: int, /, scale: int = 1) -> int:
    return x * 2 * scale


def renamed(y: int, /, scale: int = 1) -> int:
    return y + scale


def kwonly(x: int, *, scale: int) -> int:
    return x * scale


def run(h: Handler, v: int) -> int:
    return h(v)


def apply(f: Callable[[int], int], v: int) -> int:
    return f(v)


def bad_pass() -> int:
    try:
        return run(kwonly, 3)  # expect-error
    except TypeError:
        return -1


assert_type(run(double, 3), int)
assert run(double, 3) == 6
assert run(renamed, 3) == 4
assert run(lambda v, scale=1: v * scale, 2) == 2
assert apply(double, 5) == 10
assert_type(apply(lambda n: n + 1, 4), int)
assert apply(lambda n: n + 1, 4) == 5
assert bad_pass() == -1
